function csvEscape(value: string) { return /[",\n\r]/.test(value) ? `"${value.replaceAll('"', '""')}"` : value; }
function parseCSV(text: string) {
  const rows: string[][] = []; let row: string[] = [], value = "", quoted = false;
  for (let index = 0; index < text.length; index++) { const character = text[index]; if (quoted) { if (character === '"' && text[index + 1] === '"') { value += '"'; index++; } else if (character === '"') quoted = false; else value += character; } else if (character === '"' && value === "") quoted = true; else if (character === ",") { row.push(value); value = ""; } else if (character === "\n") { row.push(value.replace(/\r$/, "")); rows.push(row); row = []; value = ""; } else value += character; }
  if (value || row.length) { row.push(value.replace(/\r$/, "")); rows.push(row); } return rows;
}
